1277	static bool cjguiOhosImageKeyHex(const std::string &key,
1278	                                 std::array<char, kImageLeaseKeyHexCapacity> *out)
1279	{
1280	    static constexpr char digits[] = "0123456789abcdef";
1281	    const size_t count = std::min(key.size(), (out->size() - 1) / 2);
1282	    for (size_t i = 0; i < count; ++i) {
1283	        const unsigned char byte = static_cast<unsigned char>(key[i]);
1284	        (*out)[2 * i] = digits[byte >> 4];
1285	        (*out)[2 * i + 1] = digits[byte & 0xf];
1286	    }
1287	    (*out)[2 * count] = '\0';
1288	    return count == key.size();
1289	}
