2445	                activeJob.reset();
2446	                running = false;
2447	                g.unlock();
2448	                job->finish(CJGUI_INTERNAL_RENDERER_OK);
2449	                g.lock();
2450	                return;
2451	            }
2452	            execute(job.get());   // 共享所有权：本函数返回即释放本线程这一份引用
2453	            g.lock();
2454	            activeJob.reset();
2455	            g.unlock();
2456	            job.reset();
2457	            // finish() can wake the owner before this thread releases its own
2458	            // Present/ImageRealize reference. This is the renderer-side release
2459	            // opportunity; the owner has its separate settlement hook.
