2470	    // 停机：投递唯一 ShutdownJob、等待渲染线程 teardown 并退出、join 线程、
2471	    // 复位启动身份。非渲染线程调用；返回真实终态而不是 Bool。
2472	    CjguiInternalRendererStatus shutdownAndJoin()
2473	    {
2474	        std::lock_guard<std::mutex> serial(shutdownJoinLock);
2475	        JobRef job = std::make_shared<ShutdownJob>();
2476	        std::vector<JobRef> cancelJobs;
2477	        {
2478	            std::lock_guard<std::mutex> g(lock);
2479	            // 重复关闭只复用上一次真实结果，不为它启动一个新工作线程。
2480	            if (!running && !thread.joinable()) {
2481	                return static_cast<CjguiInternalRendererStatus>(lastShutdownStatus.load());
2482	            }
2483	            stopping = true;
2484	            if (activeJob && activeJob->kind == JobKind::Present) cancelJobs.push_back(activeJob);
2485	            for (const JobRef &pendingJob : jobs) {
2486	                if (pendingJob->kind == JobKind::Present) cancelJobs.push_back(pendingJob);
2487	            }
2488	            // 不走 post：接单已经关闭，Shutdown 仍须作为本实例唯一终止任务入队。
2489	            jobs.push_back(job);
2490	        }
2491	        // 票据临界区独立于队列锁：Committing 不可撤销；其余任务有确定取消终态。
2492	        for (const JobRef &pendingJob : cancelJobs) pendingJob->cancelBeforeCommit();
2493	        // 本 renderer 实例的测试等待由停止所有者直接唤醒；不依赖已关闭的 owner 控制通道。
2494	        cjguiOhosTestGateCancelRendererEpoch();
2495	        cv.notify_all();
2496	        std::unique_lock<std::mutex> g(job->mutex);
2497	        bool withinDeadline = job->cv.wait_for(g, std::chrono::seconds{5}, [&job]() {
2498	            return job->phase == JobPhase::Done || job->phase == JobPhase::Cancelled;
2499	        });
2500	        g.unlock();
2501	        if (thread.joinable()) thread.join();
2502	        CjguiInternalRendererStatus result = job->phaseSnapshot() == JobPhase::Done
2503	            ? job->statusSnapshot() : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
2504	        if (!withinDeadline) {
2505	            RLOGW("renderer stop exceeded five-second settlement deadline; joined status=%{public}d",
2506	                  static_cast<int>(result));
2507	        }
2508	        {
2509	            std::lock_guard<std::mutex> gl(lock);
2510	            jobs.clear();
2511	            activeJob.reset();
2512	            running = false;
2513	            stopping = false;
2514	            hasLastFrame = false;
2515	            lastNodes.clear();
2516	        }
2517	        lastShutdownStatus.store(static_cast<int32_t>(result));
2518	        return result;
2519	    }
