2773	    void executeCaretHitTest(CaretHitTestJob *job)
2774	    {
2775	        // 命中与绘制同一套排版：先按同一几何函数算出文本原点，再让排版引擎把
2776	        // (x,y) 解析成码元位置。旧实现只用 tapX 做前缀宽度二分，多行正文里点在
2777	        // 第二行会把光标落到第一行，而且 `longestLine` 对折行前缀不是该行的宽度。
2778	        if (job->text.empty()) {
2779	            job->finish(CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR);
2780	            return;
2781	        }
2782	        Measured m = layoutText(utf16ToUtf8(job->text), job->fontSize, job->fontWeight,
2783	                                job->nodeWidth, false, 0xFF000000u);
2784	        if (!m.typography) {
2785	            job->finish(CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR);
2786	            return;
2787	        }
2788	        TextGeometry geom = computeTextGeometry(0.0, 0.0, job->nodeHeight, job->nodeKind, m, job->fontSize);
2789	        OH_Drawing_PositionAndAffinity *hit = OH_Drawing_TypographyGetGlyphPositionAtCoordinateWithCluster(
2790	            m.typography, job->tapX - geom.originX, job->tapY - geom.originY);
2791	        uint32_t caretUtf16 = 0;
2792	        bool ok = false;
2793	        if (hit) {
2794	            size_t position = OH_Drawing_GetPositionFromPositionAndAffinity(hit);
2795	            caretUtf16 = clampToCodePointBoundary(job->text,
2796	                static_cast<uint32_t>(std::min<size_t>(position, job->text.size())));
2797	            ok = true;
2798	            OH_Drawing_DestroyPositionAndAffinity(hit);
2799	        }
2800	        OH_Drawing_DestroyTypography(m.typography);
2801	        if (!ok) {
2802	            job->finish(CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR);
2803	            return;
2804	        }
2805	        job->caretUtf16 = caretUtf16;
2806	        job->finish(CJGUI_INTERNAL_RENDERER_OK);
