3608	    Measured layoutText(const std::string &text, double fontSize, uint32_t fontWeight,
3609	                        double constraintWidth, bool unlimitedWidth, uint32_t textColor)
3610	    {
3611	        Measured result;
3612	        OH_Drawing_TypographyStyle *style = OH_Drawing_CreateTypographyStyle();
3613	        OH_Drawing_TextStyle *textStyle = OH_Drawing_CreateTextStyle();
3614	        OH_Drawing_SetTextStyleFontSize(textStyle, fontSize);
3615	        OH_Drawing_SetTextStyleFontWeight(textStyle, mapWeight(fontWeight));
3616	        // 共同定义的前景色由节点携带，后端不重新指定颜色。
3617	        OH_Drawing_SetTextStyleColor(textStyle, textColor);
3618	        const char *family = "HarmonyOS Sans";
3619	        OH_Drawing_SetTextStyleFontFamilies(textStyle, 1, &family);
3620	        OH_Drawing_TypographyCreate *handler =
3621	            OH_Drawing_CreateTypographyHandler(style, OH_Drawing_GetFontCollectionGlobalInstance());
3622	        OH_Drawing_TypographyHandlerPushTextStyle(handler, textStyle);
3623	        OH_Drawing_TypographyHandlerAddText(handler, text.c_str());
3624	        OH_Drawing_TypographyHandlerPopTextStyle(handler);
3625	        result.typography = OH_Drawing_CreateTypography(handler);
3626	        OH_Drawing_DestroyTypographyHandler(handler);
3627	        OH_Drawing_DestroyTextStyle(textStyle);
3628	        OH_Drawing_DestroyTypographyStyle(style);
3629	        if (!result.typography) return result;
3630	        double layoutWidth = unlimitedWidth ? 1000000.0 : constraintWidth;
3631	        if (layoutWidth < 1.0) layoutWidth = 1.0;
3632	        OH_Drawing_TypographyLayout(result.typography, layoutWidth);
3633	        result.height = OH_Drawing_TypographyGetHeight(result.typography);
3634	        result.longestLine = OH_Drawing_TypographyGetLongestLine(result.typography);
3635	        result.maxWidth = OH_Drawing_TypographyGetMaxWidth(result.typography);
3636	        result.lineCount = OH_Drawing_TypographyGetLineCount(result.typography);
3637	        result.alphabeticBaseline = OH_Drawing_TypographyGetAlphabeticBaseline(result.typography);
3638	        return result;
3639	    }
