3641	    /// 文本盒几何的唯一来源：字形绘制、光标矩形、选区高亮与触摸命中都按这里
3642	    /// 算出的原点定位。此前每处各算一次（高亮按 pod.y、字形按盒内居中、命中只有 x），
3643	    /// 结果是多行正文里"点中的行"和"看到的行"不是同一行。
3644	    struct TextGeometry {
3645	        double originX = 0.0;
3646	        double originY = 0.0;
3647	        double lineHeight = 0.0;
3648	        double textHeight = 0.0;
3649	    };
3650	
3651	    TextGeometry computeTextGeometry(double nodeX, double nodeY, double nodeHeight, uint32_t kind,
3652	                                     const Measured &m, double fontSize)
3653	    {
3654	        const double inset = (kind == kKindText) ? kTextInsetSingleLine : kTextInsetMultiline;
3655	        TextGeometry g;
3656	        g.textHeight = m.height;
3657	        g.lineHeight = m.lineCount > 0 ? m.height / static_cast<double>(m.lineCount) : fontSize * 1.2;
3658	        g.originX = nodeX + inset;
3659	        g.originY = nodeY + inset;
3660	        // 正文（多行编辑节点）从节点上沿开始排版；只有单行 label/button 才在盒内垂直居中，
3661	        // 居中会把一段短文档推到画面正中。
3662	        if (kind != kKindMultiline && m.height < nodeHeight) {
3663	            g.originY = nodeY + (nodeHeight - m.height) / 2.0;
3664	        }
3665	        return g;
3666	    }
