3668	    /// 某个码元位置的光标矩形（排版给出的 x 与该行上下沿）；排版答不出时返回 false。
3669	    bool caretRectFor(OH_Drawing_Typography *typography, uint32_t caret, uint32_t textUnits,
3670	                      double &x, double &top, double &bottom)
3671	    {
3672	        // 开头的光标取首字左沿，其余取前一字符右沿（跨行时取最后一个盒）。
3673	        size_t start = caret > 0 ? caret - 1 : 0;
3674	        size_t end = caret > 0 ? caret : std::min<size_t>(1, textUnits);
3675	        if (end <= start) return false;
3676	        OH_Drawing_TextBox *box = OH_Drawing_TypographyGetRectsForRange(typography, start, end,
3677	            RECT_HEIGHT_STYLE_TIGHT, RECT_WIDTH_STYLE_TIGHT);
3678	        if (!box) return false;
3679	        size_t count = OH_Drawing_GetSizeOfTextBox(box);
3680	        if (count == 0) {
3681	            OH_Drawing_TypographyDestroyTextBox(box);
3682	            return false;
3683	        }
3684	        int index = static_cast<int>(count - 1);
3685	        x = caret > 0 ? OH_Drawing_GetRightFromTextBox(box, index)
3686	                      : OH_Drawing_GetLeftFromTextBox(box, index);
3687	        top = OH_Drawing_GetTopFromTextBox(box, index);
3688	        bottom = OH_Drawing_GetBottomFromTextBox(box, index);
3689	        OH_Drawing_TypographyDestroyTextBox(box);
3690	        return true;
3691	    }
