3693	    /// 选区高亮：逐段矩形直接取自 accepted 排版，因此跨行选区是每行一段，
3694	    /// 而不是从选区起点宽度到终点宽度的一条整宽横杠。
3695	    void drawSelectionBoxes(OH_Drawing_Canvas *canvas, OH_Drawing_Typography *typography,
3696	                            uint32_t selStart, uint32_t selEnd, const TextGeometry &geom)
3697	    {
3698	        OH_Drawing_TextBox *boxes = OH_Drawing_TypographyGetRectsForRange(typography, selStart, selEnd,
3699	            RECT_HEIGHT_STYLE_INCLUDELINESPACEMIDDLE, RECT_WIDTH_STYLE_TIGHT);
3700	        if (!boxes) return;
3701	        size_t count = OH_Drawing_GetSizeOfTextBox(boxes);
3702	        if (count > 0) {
3703	            OH_Drawing_Brush *hl = OH_Drawing_BrushCreate();
3704	            OH_Drawing_BrushSetColor(hl, packColor(0.30, 0.50, 0.85, 0.35));
3705	            OH_Drawing_CanvasAttachBrush(canvas, hl);
3706	            for (size_t i = 0; i < count; ++i) {
3707	                int index = static_cast<int>(i);
3708	                float left = OH_Drawing_GetLeftFromTextBox(boxes, index);
3709	                float right = OH_Drawing_GetRightFromTextBox(boxes, index);
3710	                float top = OH_Drawing_GetTopFromTextBox(boxes, index);
3711	                float bottom = OH_Drawing_GetBottomFromTextBox(boxes, index);
3712	                if (right <= left) continue;   // 行尾空白等零宽段不画块
3713	                OH_Drawing_Rect *rect = OH_Drawing_RectCreate(
3714	                    static_cast<float>(geom.originX + left), static_cast<float>(geom.originY + top),
3715	                    static_cast<float>(geom.originX + right), static_cast<float>(geom.originY + bottom));
3716	                OH_Drawing_CanvasDrawRect(canvas, rect);
3717	                OH_Drawing_RectDestroy(rect);
3718	            }
3719	            OH_Drawing_CanvasDetachBrush(canvas);
3720	            OH_Drawing_BrushDestroy(hl);
3721	        }
3722	        OH_Drawing_TypographyDestroyTextBox(boxes);
3723	    }
