3725	    static int mapWeight(uint32_t weight)
3726	    {
3727	        if (weight < 100) return FONT_WEIGHT_400;
3728	        int step = (static_cast<int>(weight) + 50) / 100 * 100;
3729	        if (step < 100) step = 100;
3730	        if (step > 900) step = 900;
3731	        return step;
3732	    }
