7591	            RawTouchSample sample{};
7592	            sample.pointerId = -1;
7593	            int rc = g_ingress.touchDequeueEx(&sample.action, &sample.x, &sample.y,
7594	                &sample.appInstance, &sample.componentInstance,
7595	                &sample.surfaceGeneration, &sample.pointerId, &sample.gestureEpoch,
7596	                &sample.timestampNs, &sample.timeSource);
7597	            if (rc != 1) break;  // 0 空 / -1 旧代已丢弃
