5410	// System ICU is the platform boundary oracle. Each call owns its library handle,
5411	// immutable UTF-16 buffer and iterator; destruction closes the iterator before
5412	// releasing the buffer/library. Missing symbols/rule data is a named refusal.
5413	// UTF-8/UTF-16 mapping below maps scalars only, never implements UAX#29.
5414	#ifndef CJGUI_OHOS_ICU_LIBRARY
5415	#define CJGUI_OHOS_ICU_LIBRARY "libicu.so"
5416	#endif
5417	struct CjguiOhosIcuApi {
5418	    void *handle = nullptr;
5419	    decltype(&u_strFromUTF8) fromUtf8 = nullptr;
5420	    decltype(&ubrk_open) open = nullptr;
5421	    decltype(&ubrk_close) close = nullptr;
5422	    decltype(&ubrk_isBoundary) isBoundary = nullptr;
5423	    decltype(&ubrk_preceding) preceding = nullptr;
5424	    decltype(&ubrk_following) following = nullptr;
5425	    CjguiOhosIcuApi() {
5426	        handle = dlopen(CJGUI_OHOS_ICU_LIBRARY, RTLD_NOW | RTLD_LOCAL);
5427	        if (!handle) return;
5428	        fromUtf8 = reinterpret_cast<decltype(fromUtf8)>(dlsym(handle, "u_strFromUTF8"));
5429	        open = reinterpret_cast<decltype(open)>(dlsym(handle, "ubrk_open"));
5430	        close = reinterpret_cast<decltype(close)>(dlsym(handle, "ubrk_close"));
5431	        isBoundary = reinterpret_cast<decltype(isBoundary)>(dlsym(handle, "ubrk_isBoundary"));
5432	        preceding = reinterpret_cast<decltype(preceding)>(dlsym(handle, "ubrk_preceding"));
5433	        following = reinterpret_cast<decltype(following)>(dlsym(handle, "ubrk_following"));
5434	    }
5435	    ~CjguiOhosIcuApi() { if (handle) dlclose(handle); }
5436	    bool ready() const { return fromUtf8 && open && close && isBoundary && preceding && following; }
5437	    CjguiOhosIcuApi(const CjguiOhosIcuApi&) = delete;
5438	    CjguiOhosIcuApi& operator=(const CjguiOhosIcuApi&) = delete;
5439	};
