5441	extern "C" CjguiInternalRendererStatus cjgui_internal_renderer_grapheme_cluster_range(
5442	    const char *utf8, uint64_t declaredLength, uint64_t offsetByte,
5443	    uint64_t *outStartByte, uint64_t *outEndByte)
5444	{
5445	    if (outStartByte) *outStartByte = 0;
5446	    if (outEndByte) *outEndByte = 0;
5447	    if (!utf8 || !outStartByte || !outEndByte) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
5448	    if (declaredLength > static_cast<uint64_t>(INT32_MAX - 1)) {
5449	        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
5450	    }
5451	    // The FFI caller owns a CString allocation. A NUL before the declared end,
5452	    // or a different CString length, cannot stand in for the original bytes.
5453	    if (strnlen(utf8, static_cast<size_t>(declaredLength + 1)) != declaredLength) {
5454	        return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
5455	    }
5456	    if (offsetByte >= declaredLength) return CJGUI_INTERNAL_RENDERER_GRAPHEME_BOUNDARY_INVALID;
5457	    CjguiOhosIcuApi api;
5458	    if (!api.ready()) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
5459	    try {
5460	        UErrorCode error = U_ZERO_ERROR;
5461	        int32_t units = 0;
5462	        api.fromUtf8(nullptr, 0, &units, utf8, static_cast<int32_t>(declaredLength), &error);
5463	        if (error != U_BUFFER_OVERFLOW_ERROR && U_FAILURE(error)) {
5464	            return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
5465	        }
5466	        error = U_ZERO_ERROR;
5467	        std::vector<UChar> text(static_cast<size_t>(units) + 1);
5468	        api.fromUtf8(text.data(), static_cast<int32_t>(text.size()), &units, utf8,
5469	                     static_cast<int32_t>(declaredLength), &error);
5470	        if (U_FAILURE(error)) return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
5471	        struct ScalarBoundary { uint64_t byte; int32_t unit; };
5472	        std::vector<ScalarBoundary> boundaries;
5473	        uint64_t byte = 0;
5474	        int32_t unit = 0, targetUnit = -1;
5475	        // ICU already strictly decoded these bytes; this only records each
5476	        // scalar's byte/unit position, including a query inside its bytes.
5477	        while (byte < declaredLength) {
5478	            boundaries.push_back({byte, unit});
5479	            const auto lead = static_cast<unsigned char>(utf8[byte]);
5480	            const uint64_t size = lead < 0x80 ? 1 : (lead < 0xe0 ? 2 : (lead < 0xf0 ? 3 : 4));
5481	            if (byte <= offsetByte && offsetByte < byte + size) targetUnit = unit;
5482	            byte += size;
5483	            unit += size == 4 ? 2 : 1;
5484	        }
5485	        boundaries.push_back({byte, unit});
5486	        if (byte != declaredLength || unit != units || targetUnit < 0) {
5487	            return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
5488	        }
5489	        error = U_ZERO_ERROR;
5490	        std::unique_ptr<UBreakIterator, decltype(api.close)> iterator(
5491	            api.open(UBRK_CHARACTER, "root", text.data(), units, &error), api.close);
5492	        if (!iterator || U_FAILURE(error)) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
5493	        const int32_t start = api.isBoundary(iterator.get(), targetUnit) ? targetUnit :
5494	                              api.preceding(iterator.get(), targetUnit);
5495	        const int32_t end = api.following(iterator.get(), targetUnit);
5496	        uint64_t startByte = UINT64_MAX, endByte = UINT64_MAX;
