5991	CjguiInternalRendererStatus cjgui_internal_renderer_destroy(uint64_t session)
5992	{
5993	    std::unique_lock<std::mutex> g(g_sessions.lock);
5994	    int slot = sessionSlotLocked(session);
5995	    Session *s = lookupSessionLocked(session);
5996	    if (!s) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
5997	    // A1：仍有未确认（未 ACK）票据时拒绝销毁。直接清 g_pending 只能阻止槽位
5998	    // 误认领，不能证明原事务已结算；旧实例身份也不得在资源仍存活时被复用。
5999	    // 调用方必须先 query 取得终态、acknowledge 回收，再销毁。
6000	    if (slot >= 0 && g_pending[slot].valid) {
6001	        s->ticketDestroyRefusedCount += 1;
6002	        RLOGW("destroy refused: unacknowledged ticket=%{public}llu",
6003	              static_cast<unsigned long long>(g_pending[slot].ticketId));
6004	        return CJGUI_INTERNAL_RENDERER_PENDING_SETTLEMENT_UNRESOLVED;
6005	    }
6006	    const uint64_t oldProjection = s->acceptedProjectionVersion;
6007	    std::vector<SceneNode> oldAccepted;
6008	    oldAccepted.swap(s->accepted);
6009	    s->acceptedProjectionVersion = 0;
6010	    cjguiOhosLogAcceptedImageSwap(*s, oldAccepted, oldProjection, 0, "destroy");
6011	    oldAccepted.clear();
6012	    s->inUse = false;
6013	    s->token = 0;
6014	    s->candidate.clear();
6015	    s->imageObservedSerial.clear();
6016	    s->events.clear();
6017	    s->gesture = Session::TouchGesture{};  // B：销毁即取消，旧相位不得延续
6018	    s->editing = false;
6019	    s->editingText.clear();
6020	    s->previewText.clear();
6021	    if (slot >= 0) {
6022	        // 会话销毁不得让待结算票据在下一实例里被当作自己的（防 ABA）；
6023	        // 旧票据只由原共享所有权自然回收，不再参与任何晋升。
6024	        g_pending[slot].job = nullptr;
6025	        g_pending[slot].nodes.clear();
6026	        g_pending[slot].valid = false;
6027	    }
6028	    g_sessions.occupied -= 1;
6029	    g.unlock();
6030	    cjguiOhosPruneReleasedImages();
6031	    return CJGUI_INTERNAL_RENDERER_OK;
6032	}

