  8037	// Pure platform query: verifies the captured proxy baseline under the native
  8038	// context lock. It neither locks nor edits the Cangjie owner; kind51 retains
  8039	// its original owner arbitration after the REAL platform change.
  8040	extern "C" int32_t ohos_renderer_ime_grapheme_range_ctx(const char *text, size_t length,
  8041	    int32_t offset16, int64_t contextId, int32_t *outStart, int32_t *outEnd)
  8042	{
  8043	    if (outStart) *outStart = 0;
  8044	    if (outEnd) *outEnd = 0;
  8045	    if (!text || !outStart || !outEnd || length > 65536) return 16;
  8046	    const std::string input(text, length);
  8047	    std::lock_guard<std::mutex> g(g_sessions.lock);
  8048	    Session *s = takeEditingContextLocked(contextId);
  8049	    if (!s || s->previewActive || s->markedActive || s->proxyRestore.armed ||
  8050	        s->proxyRestore.awaitingAck || s->proxyRestore.platformInstalled ||
  8051	        utf16ToUtf8(s->editingText) != input) return 1;
  8052	    if (offset16 < 0 || static_cast<size_t>(offset16) >= s->editingText.size()) return 24;
  8053	    uint32_t scalar = static_cast<uint32_t>(offset16);
  8054	    if (scalar > 0 && s->editingText[scalar] >= 0xdc00 && s->editingText[scalar] <= 0xdfff &&
  8055	        s->editingText[scalar - 1] >= 0xd800 && s->editingText[scalar - 1] <= 0xdbff) --scalar;
  8056	    const uint64_t byte = utf16ToUtf8(s->editingText.substr(0, scalar)).size();
  8057	    uint64_t start = 0, end = 0;
  8058	    const auto status = cjgui_internal_renderer_grapheme_cluster_range(input.c_str(), input.size(), byte, &start, &end);
  8059	    if (status != CJGUI_INTERNAL_RENDERER_OK) return status;
  8060	    *outStart = static_cast<int32_t>(utf8ToUtf16(input.substr(0, start)).size());
  8061	    *outEnd = static_cast<int32_t>(utf8ToUtf16(input.substr(0, end)).size());
  8062	    return 0;
  8063	}
