  8100	    // 真实提交共同经过这里（onChange 整值变化与无 marked 的预览折入都走本入口）：
  8101	    // 人的编辑取代未完成的恢复，取消必须放在共同入口而不是某一个 ABI 外壳里。
  8102	    cancelProxyRestoreRequest(s, "human_commit_supersedes");
  8103	    const std::u16string previous = s.editingText;
  8104	    s.editingText = next;
  8105	    s.caretUtf16 = static_cast<uint32_t>(s.editingText.size());
  8106	    s.selStartUtf16 = s.caretUtf16;
  8107	    s.selEndUtf16 = s.caretUtf16;
  8108	    s.previewActive = false;
