  8110	    s.markedActive = false;
  8111	    // 畸形输入被具名拒绝时编辑缓冲已由 `editorEnqueueTextCommit` 恢复为
  8112	    // previous：这里仍返回 true（该变化由提交路径处理完毕），否则调用方会把
  8113	    // 同一段畸形文本当成视觉预览再贴回来。
  8114	    const bool committed = editorEnqueueTextCommit(s, previous, s.editingText);
