  8216	        uint32_t size = static_cast<uint32_t>(visible.size());
  8217	        uint32_t a = clampToCodePointBoundary(visible, static_cast<uint32_t>(std::max(0, start)));
  8218	        uint32_t b = clampToCodePointBoundary(visible, static_cast<uint32_t>(std::max(0, end)));
  8219	        a = std::min(a, size);
  8220	        b = std::min(b, size);
  8221	        changed = (s->selStartUtf16 != a) || (s->selEndUtf16 != b) || (s->caretUtf16 != b);
  8222	        // 转发判据与 changed 分开：平台装好人的落点之后回声的值常常正好等于命中测试
  8223	        // 写下的 native 值（changed=false），而窗口恰恰需要这条"平台已安装"的观测才能
  8224	        // 核验人类锚、解除外部换版留下的输入门禁。按 changed 判重就是首字丢失的根因。
  8225	        const bool forward = selectionObservationNeedsForwarding(*s, a, b);
  8226	        if (forward && !editorEnqueueSelectionChanged(*s, a, b)) {
  8227	            RLOGW("ime selection rejected: no matching accepted binding ctx=%{public}lld node=%{public}llu",
  8228	                  static_cast<long long>(contextId), static_cast<unsigned long long>(s->editingNodeId));
  8229	            return 1;
  8230	        }
  8231	        if (forward) {
  8232	            rememberForwardedSelectionLocked(*s, a, b);
  8233	            if (!changed) {
  8234	                RLOGI("ime selection observation forwarded ctx=%{public}lld sel=%{public}u:%{public}u native_changed=0",
  8235	                      static_cast<long long>(contextId), a, b);
  8236	            }
  8237	        }
