 204	    OH_Drawing_RectHeightStyle heightStyle, OH_Drawing_RectWidthStyle widthStyle) {
 205	  (void)heightStyle; (void)widthStyle;
 206	  if (!t || end <= start) return nullptr;
 207	  const double advance = t->fontSize * g_advanceFactor;
 208	  FakeTextBox *box = new FakeTextBox();
 209	  for (const FakeLine &line : t->lines) {
 210	    const size_t a = std::max(start, line.start);
 211	    const size_t b = std::min(end, line.end);
 212	    if (b <= a) continue;
 213	    std::array<double, 4> rect;
 214	    rect[0] = static_cast<double>(a - line.start) * advance;
 215	    rect[1] = line.top;
 216	    rect[2] = static_cast<double>(b - line.start) * advance;
 217	    rect[3] = line.bottom;
 218	    box->boxes.push_back(rect);
 219	  }
 220	  return box;
 221	}
