  4812	// IME 视角的缓冲：基础文本 + 组合预览内联。
  4813	std::u16string composedBuffer(const Session &s)
  4814	{
  4815	    if (!s.previewActive) return s.editingText;
  4816	    uint32_t start = std::min(s.previewStart, static_cast<uint32_t>(s.editingText.size()));
  4817	    uint32_t end = std::min(std::max(s.previewEnd, start), static_cast<uint32_t>(s.editingText.size()));
  4818	    std::u16string out = s.editingText.substr(0, start);
  4819	    out += s.previewText;
  4820	    out += s.editingText.substr(end);
  4821	    return out;
  4822	}
